-- A sheet's terms (whole days): a claim is due by its date plus the terms. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- A sheet's policy date: a claim dated before it rounds half up, one dated on or after it rounds half
-- to even. Null (blank) takes the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- A sheet's terms (whole days): a claim is due by its date plus the terms. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- A sheet's late percent (two decimals): an overdue claim's due gains it of its figure for every
-- full 30 days it is overdue. A sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(12, 2) DEFAULT 0.00 NOT NULL;
-- A person's patrons: other people on the same sheet the person names, each at most once.
CREATE TABLE person_patron (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_pair ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- A person's grade is dated: each grade a person is given applies from its from-date, and the one in
-- force on a date is the one whose from-date is the latest on or before it. The first grade a person
-- was given has no from-date and applies from the beginning of time. A person has at most one grade
-- per from-date (no from-date counting as one).
CREATE TABLE person_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade CHAR(1) NOT NULL,
    from_date DATE,
    from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_person_from ON person_grade (person_id, from_key);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the same
-- person that it corrects. The amount may now be below 0.00 (its first check is dropped with the
-- column it was declared on), and only a correction names a claim it corrects.
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(12, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD COLUMN corrects_number BIGINT;
ALTER TABLE claim ADD CONSTRAINT claim_correction_names CHECK ((amount < 0) = (corrects_number IS NOT NULL));
-- A sheet's policy date: a claim dated before it rounds half up, one dated on or after it rounds half
-- to even. Null (blank) takes the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- A sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim
-- opened is numbered within its period (<period>-<n>), or X-<n> when its date falls in no period.
-- Null (blank) is off: claims take the sheet-wide number. Claim numbers, and the numbers corrections
-- name, become text so they can hold either form.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects_number SET DATA TYPE VARCHAR(255);
-- A claim a clerk settles above the clerk limit is PENDING until a steward approves or rejects it.
ALTER TABLE claim DROP CONSTRAINT claim_status_known;
ALTER TABLE claim ADD CONSTRAINT claim_status_known CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
-- A claim is listed under its person newest first by when it was listed there: when it was added,
-- or when it was last reassigned to them (a reassigned claim is its new person's newest).
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- A sheet's "today": the date every date-dependent decision and default on the sheet uses. It
-- starts as the real date when the sheet is first loaded and is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it, and its clerk limit, its floor, its terms and
 *  its late percent, its policy date and its period numbering from. */
@Service
public class SettingService {

    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final SheetRoleRepository roles;
    private final Audit audit;

    public SettingService(SheetService sheets, SheetRepository sheetRepository, SheetRoleRepository roles,
            Audit audit) {
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.roles = roles;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless assigned another. */
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** The sheet's clerk limit; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return sheets.load(sheetId).getClerkLimit();
    }

    /** The sheet's floor: the least a claim's live due can be. */
    public BigDecimal floor(String sheetId) {
        return sheets.load(sheetId).getFloor();
    }

    /** The sheet's terms in days: a claim is due by its date plus them. */
    public int terms(String sheetId) {
        return sheets.load(sheetId).getTerms();
    }

    /** The sheet's late percent: an overdue claim's due gains it of its figure for every full 30 days
     *  it is overdue. */
    public BigDecimal latePct(String sheetId) {
        return sheets.load(sheetId).getLatePct();
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today applies). */
    public LocalDate policyDateSet(String sheetId) {
        return sheets.load(sheetId).getPolicyDate();
    }

    /** The sheet's policy date in force: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = policyDateSet(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** The sheet's period numbering from; null when it is blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.load(sheetId).getPeriodNumberingFrom();
    }

    /** How a claim dated on the given date rounds: half up before the policy date, half to even on or
     *  after it. */
    public RoundingMode roundingOn(String sheetId, LocalDate date) {
        return date.isBefore(policyDate(sheetId)) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Assign a user name a role on the sheet. */
    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        sheets.lock(sheetId);
        SheetRole saved = roles.findBySheetIdAndUser(sheetId, user)
                .map(existing -> {
                    existing.setRole(role);
                    return existing;
                })
                .orElseGet(() -> new SheetRole(sheetId, user, role));
        saved = roles.saveAndFlush(saved);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role.label());
        return saved;
    }

    /** Change the sheet's clerk limit; null removes it. */
    @Transactional
    public Sheet setClerkLimit(String sheetId, String by, BigDecimal limit) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        BigDecimal scaled = limit != null ? limit.setScale(2, RoundingMode.UNNECESSARY) : null;
        sheet.setClerkLimit(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=clerk-limit value="
                + (scaled != null ? scaled.toPlainString() : ""));
        return saved;
    }

    /** Change the sheet's floor. */
    @Transactional
    public Sheet setFloor(String sheetId, String by, BigDecimal floor) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        BigDecimal scaled = floor.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setFloor(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=floor value="
                + scaled.toPlainString());
        return saved;
    }

    /** Change the sheet's terms. */
    @Transactional
    public Sheet setTerms(String sheetId, String by, int terms) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setTerms(terms);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=terms value=" + terms);
        return saved;
    }

    /** Change the sheet's late percent. */
    @Transactional
    public Sheet setLatePct(String sheetId, String by, BigDecimal latePct) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        BigDecimal scaled = latePct.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setLatePct(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=late-pct value="
                + scaled.toPlainString());
        return saved;
    }

    /** Change the sheet's policy date; null leaves it blank (the sheet's today). */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String by, LocalDate policyDate) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=policy-date value="
                + (policyDate != null ? policyDate.toString() : ""));
        return saved;
    }

    /** Change the sheet's period numbering from; null leaves it blank (off). */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String by, LocalDate from) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=period-numbering-from value="
                + (from != null ? from.toString() : ""));
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.DecimalMin;
