ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- A sheet's policy date: a claim dated before it rounds half up, one dated on or after it rounds half
-- to even. Null (blank) takes the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- A sheet's terms (whole days): a claim is due by its date plus the terms. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- A sheet's late percent (two decimals): an overdue claim's due gains it of its figure for every
-- full 30 days it is overdue. A sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(12, 2) DEFAULT 0.00 NOT NULL;
-- A person's patrons: other people on the same sheet the person names, each at most once.
CREATE TABLE person_patron (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_pair ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- A person's grade is dated: each grade a person is given applies from its from-date, and the one in
-- force on a date is the one whose from-date is the latest on or before it. The first grade a person
-- was given has no from-date and applies from the beginning of time. A person has at most one grade
-- per from-date (no from-date counting as one).
CREATE TABLE person_grade (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade CHAR(1) NOT NULL,
    from_date DATE,
    from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_person_from ON person_grade (person_id, from_key);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the same
-- person that it corrects. The amount may now be below 0.00 (its first check is dropped with the
-- column it was declared on), and only a correction names a claim it corrects.
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(12, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD COLUMN corrects_number BIGINT;
ALTER TABLE claim ADD CONSTRAINT claim_correction_names CHECK ((amount < 0) = (corrects_number IS NOT NULL));
-- A sheet's policy date: a claim dated before it rounds half up, one dated on or after it rounds half
-- to even. Null (blank) takes the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- A sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim
-- opened is numbered within its period (<period>-<n>), or X-<n> when its date falls in no period.
-- Null (blank) is off: claims take the sheet-wide number. Claim numbers, and the numbers corrections
-- name, become text so they can hold either form.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(255);
