  const halfUp = roundsHalfUp(claim, late);
  const figure = figureCents(claim, rates, floor, halfUp);
  if (figure === null) return null;
  const periods = isCorrection(claim) ? 0 : Math.floor(daysOverdue(claim, late) / 30);
